-- VieMo: every database migration in one file, in order. Generated by scripts/bundle-migrations.mjs; don't edit by hand.
-- For a NEW, empty Supabase project: paste all of it into SQL Editor → New query, and press Run.
-- It runs as one transaction: if anything fails, nothing is changed. Supabase will warn about "destructive
-- operations": that is expected (the file revokes default permissions and defines functions that delete rows later).
-- If some migrations have already run, use the individual files in supabase/migrations/ instead.
-- Includes: 20261018000001_foundation.sql, 20261018000002_library.sql, 20261018000003_sceneatlas.sql, 20261019000004_screening_activity.sql, 20261020000005_community.sql, 20261021000006_wheelmo.sql, 20261022000007_movie_nights.sql, 20261023000008_private_usernames.sql

begin;

-- ==================== 20261018000001_foundation.sql ====================
-- REEL / VieMo foundation: the film cache every other table points at, profiles for accounts, and follows.
-- Row level security is on for every table and denies by default; each policy below is the only way in.
-- Safe to run once on a fresh Supabase project (SQL Editor, or `supabase db push`).

create schema if not exists extensions;
create extension if not exists citext with schema extensions;

-- Shared helper: keep updated_at honest.
create or replace function public.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end $$;
revoke all on function public.touch_updated_at() from public, anon, authenticated;

------------------------------------------------------------------------------------------------------------------
-- films: a cache of TMDB facts. Only the server writes it (service role), always from TMDB, so a film id
-- anywhere in the database is a real TMDB film.
------------------------------------------------------------------------------------------------------------------
create table public.films (
  tmdb_id     integer primary key check (tmdb_id > 0),
  title       text not null check (char_length(title) between 1 and 300),
  year        smallint check (year between 1870 and 2100),
  poster_path text check (poster_path ~ '^/[A-Za-z0-9._-]+$'),
  genres      text[] not null default '{}' check (cardinality(genres) <= 12),
  runtime     smallint check (runtime between 1 and 1000),
  fetched_at  timestamptz not null default now()
);
alter table public.films enable row level security;
revoke all on public.films from anon, authenticated;
create policy "films are readable by everyone" on public.films for select to anon, authenticated using (true);
grant select on public.films to anon, authenticated;

------------------------------------------------------------------------------------------------------------------
-- profiles: one per account, created automatically at sign-up.
------------------------------------------------------------------------------------------------------------------
create table public.profiles (
  id                   uuid primary key references auth.users (id) on delete cascade,
  username             extensions.citext not null unique check (username::text ~ '^[a-z0-9_]{3,24}$'),
  display_name         text check (char_length(display_name) <= 60),
  avatar_url           text check (avatar_url is null or avatar_url ~ '^https://'),
  bio                  text check (char_length(bio) <= 280),
  watchlist_visibility text not null default 'private' check (watchlist_visibility in ('private', 'public')),
  onboarded            boolean not null default false,
  is_editor            boolean not null default false,   -- set by the site owner in Supabase; never by users
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);
alter table public.profiles enable row level security;
revoke all on public.profiles from anon, authenticated;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at();

-- Profiles are public (username, name, avatar), so collections and match rooms can show who's who.
create policy "profiles are readable by everyone" on public.profiles for select to anon, authenticated using (true);
create policy "people edit their own profile" on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
grant select on public.profiles to anon, authenticated;
-- Column-level: people can change these, and nothing else (not is_editor, not id).
grant update (username, display_name, avatar_url, bio, watchlist_visibility, onboarded) on public.profiles to authenticated;

-- A new account gets a profile with a username made from the email, made unique with a short suffix.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  base text := left(regexp_replace(lower(split_part(coalesce(new.email, 'member'), '@', 1)), '[^a-z0-9_]', '', 'g'), 16);
  candidate text;
begin
  if char_length(base) < 3 then base := 'member'; end if;
  loop
    candidate := base || '_' || substr(md5(random()::text || clock_timestamp()::text), 1, 4);
    exit when not exists (select 1 from public.profiles p where p.username = candidate::extensions.citext);
  end loop;
  insert into public.profiles (id, username, display_name)
  values (new.id, candidate, nullif(left(coalesce(new.raw_user_meta_data ->> 'display_name', ''), 60), ''));
  return new;
end $$;
revoke all on function public.handle_new_user() from public, anon, authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

------------------------------------------------------------------------------------------------------------------
-- follows: who follows whom. Public, like profiles.
------------------------------------------------------------------------------------------------------------------
create table public.follows (
  follower_id uuid not null references public.profiles (id) on delete cascade,
  followee_id uuid not null references public.profiles (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, followee_id),
  check (follower_id <> followee_id)
);
create index follows_followee on public.follows (followee_id);
alter table public.follows enable row level security;
revoke all on public.follows from anon, authenticated;
create policy "follows are readable by everyone" on public.follows for select to anon, authenticated using (true);
create policy "people follow as themselves" on public.follows for insert to authenticated with check (follower_id = (select auth.uid()));
create policy "people unfollow as themselves" on public.follows for delete to authenticated using (follower_id = (select auth.uid()));
grant select on public.follows to anon, authenticated;
grant insert, delete on public.follows to authenticated;

-- ==================== 20261018000002_library.sql ====================
-- My Cinema Library: watchlist, diary (Wall of Fame), favourites and collections with collaborators and saves.
-- Visibility is enforced here, not in the interface: private rows never leave the database for anyone else.

------------------------------------------------------------------------------------------------------------------
-- Watchlist. Private unless the owner sets profiles.watchlist_visibility = 'public'.
------------------------------------------------------------------------------------------------------------------
create table public.watchlist_items (
  user_id   uuid not null references public.profiles (id) on delete cascade,
  tmdb_id   integer not null references public.films (tmdb_id),
  note      text check (char_length(note) <= 500),
  added_at  timestamptz not null default now(),
  primary key (user_id, tmdb_id)
);
create index watchlist_by_film on public.watchlist_items (tmdb_id);
alter table public.watchlist_items enable row level security;
revoke all on public.watchlist_items from anon, authenticated;
create policy "owners read their watchlist; anyone reads a public one" on public.watchlist_items for select to anon, authenticated
  using (user_id = (select auth.uid())
         or exists (select 1 from public.profiles p where p.id = user_id and p.watchlist_visibility = 'public'));
create policy "owners add to their watchlist" on public.watchlist_items for insert to authenticated with check (user_id = (select auth.uid()));
create policy "owners edit their watchlist" on public.watchlist_items for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "owners remove from their watchlist" on public.watchlist_items for delete to authenticated using (user_id = (select auth.uid()));
grant select on public.watchlist_items to anon, authenticated;
grant insert (user_id, tmdb_id, note), delete on public.watchlist_items to authenticated;
grant update (note) on public.watchlist_items to authenticated;

------------------------------------------------------------------------------------------------------------------
-- Diary: every watch, rating and review (the Wall of Fame's data). Private to its owner for now.
------------------------------------------------------------------------------------------------------------------
create table public.diary_entries (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  tmdb_id     integer not null references public.films (tmdb_id),
  watched_on  date not null check (watched_on <= current_date + 1),
  rating      numeric(2, 1) check (rating between 0.5 and 5 and rating * 2 = floor(rating * 2)),
  review      text check (char_length(review) <= 5000),
  spoiler     boolean not null default false,
  notes       text check (char_length(notes) <= 1000),
  tags        text[] not null default '{}' check (cardinality(tags) <= 12),
  created_at  timestamptz not null default now()
);
create index diary_by_user on public.diary_entries (user_id, watched_on desc);
create index diary_by_film on public.diary_entries (tmdb_id);
alter table public.diary_entries enable row level security;
revoke all on public.diary_entries from anon, authenticated;
create policy "owners manage their diary" on public.diary_entries for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant select, delete on public.diary_entries to authenticated;
grant insert (user_id, tmdb_id, watched_on, rating, review, spoiler, notes, tags) on public.diary_entries to authenticated;
grant update (watched_on, rating, review, spoiler, notes, tags) on public.diary_entries to authenticated;

create table public.favourites (
  user_id    uuid not null references public.profiles (id) on delete cascade,
  tmdb_id    integer not null references public.films (tmdb_id),
  created_at timestamptz not null default now(),
  primary key (user_id, tmdb_id)
);
alter table public.favourites enable row level security;
revoke all on public.favourites from anon, authenticated;
create policy "owners manage their favourites" on public.favourites for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant select, delete on public.favourites to authenticated;
grant insert (user_id, tmdb_id) on public.favourites to authenticated;

------------------------------------------------------------------------------------------------------------------
-- Collections. private (owner and collaborators), unlisted (also anyone with the share link, through
-- get_collection_by_share only, never in lists or search), public (everyone).
------------------------------------------------------------------------------------------------------------------
-- array_to_string is only "stable" in Postgres; for text[] it can't vary, so this wrapper is safely immutable
-- and can feed the generated search column.
create or replace function public.tags_text(tags text[]) returns text language sql immutable parallel safe set search_path = '' as $$
  select coalesce(array_to_string(tags, ' '), '')
$$;

create table public.movie_collections (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null references public.profiles (id) on delete cascade,
  title         text not null check (char_length(btrim(title)) between 1 and 120),
  description   text check (char_length(description) <= 2000),
  tags          text[] not null default '{}' check (cardinality(tags) <= 10),
  cover_tmdb_id integer references public.films (tmdb_id),
  visibility    text not null default 'private' check (visibility in ('private', 'unlisted', 'public')),
  share_id      text not null unique default substr(replace(gen_random_uuid()::text, '-', ''), 1, 16),
  copied_from   uuid references public.movie_collections (id) on delete set null,
  published_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  search        tsvector generated always as (
                  setweight(to_tsvector('simple'::regconfig, coalesce(title, '')), 'A') ||
                  setweight(to_tsvector('simple'::regconfig, public.tags_text(tags)), 'B') ||
                  setweight(to_tsvector('simple'::regconfig, coalesce(description, '')), 'C')) stored
);
create index collections_by_owner on public.movie_collections (owner_id);
create index collections_public_recent on public.movie_collections (published_at desc) where visibility = 'public';
create index collections_search on public.movie_collections using gin (search);
create index collections_tags on public.movie_collections using gin (tags);
create trigger collections_touch before update on public.movie_collections for each row execute function public.touch_updated_at();

-- published_at marks the first time a collection went public (for "recently published").
create or replace function public.stamp_published() returns trigger language plpgsql set search_path = '' as $$
begin
  if new.visibility = 'public' and new.published_at is null then new.published_at := now(); end if;
  return new;
end $$;
revoke all on function public.stamp_published() from public, anon, authenticated;
create trigger collections_publish before insert or update of visibility on public.movie_collections
  for each row execute function public.stamp_published();

create table public.collection_items (
  collection_id uuid not null references public.movie_collections (id) on delete cascade,
  tmdb_id       integer not null references public.films (tmdb_id),
  position      integer not null check (position >= 0),
  note          text check (char_length(note) <= 500),
  added_by      uuid references public.profiles (id) on delete set null,
  added_at      timestamptz not null default now(),
  primary key (collection_id, tmdb_id)
);
create index collection_items_order on public.collection_items (collection_id, position);
create index collection_items_by_film on public.collection_items (tmdb_id);

create table public.collection_collaborators (
  collection_id uuid not null references public.movie_collections (id) on delete cascade,
  user_id       uuid not null references public.profiles (id) on delete cascade,
  role          text not null check (role in ('editor', 'viewer')),
  invited_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  primary key (collection_id, user_id)
);
create index collaborators_by_user on public.collection_collaborators (user_id);

create table public.collection_saves (
  user_id       uuid not null references public.profiles (id) on delete cascade,
  collection_id uuid not null references public.movie_collections (id) on delete cascade,
  saved_at      timestamptz not null default now(),
  primary key (user_id, collection_id)
);
create index saves_by_collection on public.collection_saves (collection_id);

-- Membership checks run as the definer so policies on related tables don't recurse into each other.
create or replace function public.collection_role(cid uuid) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when c.owner_id = (select auth.uid()) then 'owner'
    else (select cc.role from public.collection_collaborators cc where cc.collection_id = cid and cc.user_id = (select auth.uid()))
  end
  from public.movie_collections c where c.id = cid
$$;
create or replace function public.can_view_collection(cid uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.movie_collections c where c.id = cid and c.visibility = 'public')
      or public.collection_role(cid) is not null
$$;
create or replace function public.can_edit_collection_items(cid uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(public.collection_role(cid) in ('owner', 'editor'), false)
$$;
revoke all on function public.collection_role(uuid), public.can_view_collection(uuid), public.can_edit_collection_items(uuid) from public, anon, authenticated;
grant execute on function public.collection_role(uuid), public.can_view_collection(uuid), public.can_edit_collection_items(uuid) to anon, authenticated;

alter table public.movie_collections enable row level security;
revoke all on public.movie_collections from anon, authenticated;
alter table public.collection_items enable row level security;
revoke all on public.collection_items from anon, authenticated;
alter table public.collection_collaborators enable row level security;
revoke all on public.collection_collaborators from anon, authenticated;
alter table public.collection_saves enable row level security;
revoke all on public.collection_saves from anon, authenticated;

-- Collections: public ones for everyone; private and unlisted ones only for the owner and collaborators.
create policy "public collections and your own" on public.movie_collections for select to anon, authenticated
  using (visibility = 'public' or owner_id = (select auth.uid()) or public.collection_role(id) is not null);
create policy "you create collections as yourself" on public.movie_collections for insert to authenticated with check (owner_id = (select auth.uid()));
-- Only the owner changes a collection's details and visibility; editors change its films.
create policy "owners edit their collections" on public.movie_collections for update to authenticated
  using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "owners delete their collections" on public.movie_collections for delete to authenticated using (owner_id = (select auth.uid()));
grant select on public.movie_collections to anon, authenticated;
grant delete on public.movie_collections to authenticated;
grant insert (owner_id, title, description, tags, cover_tmdb_id, visibility) on public.movie_collections to authenticated;
grant update (title, description, tags, cover_tmdb_id, visibility) on public.movie_collections to authenticated;

create policy "films in collections you can see" on public.collection_items for select to anon, authenticated using (public.can_view_collection(collection_id));
create policy "owners and editors add films" on public.collection_items for insert to authenticated
  with check (public.can_edit_collection_items(collection_id) and added_by = (select auth.uid()));
create policy "owners and editors reorder films" on public.collection_items for update to authenticated
  using (public.can_edit_collection_items(collection_id)) with check (public.can_edit_collection_items(collection_id));
create policy "owners and editors remove films" on public.collection_items for delete to authenticated using (public.can_edit_collection_items(collection_id));
grant select on public.collection_items to anon, authenticated;
grant delete on public.collection_items to authenticated;
grant insert (collection_id, tmdb_id, position, note, added_by) on public.collection_items to authenticated;
grant update (position, note) on public.collection_items to authenticated;

create policy "owners see collaborators; collaborators see themselves" on public.collection_collaborators for select to authenticated
  using (user_id = (select auth.uid()) or public.collection_role(collection_id) = 'owner');
create policy "owners invite collaborators" on public.collection_collaborators for insert to authenticated
  with check (public.collection_role(collection_id) = 'owner' and invited_by = (select auth.uid()) and user_id <> (select auth.uid()));
create policy "owners change roles" on public.collection_collaborators for update to authenticated
  using (public.collection_role(collection_id) = 'owner') with check (public.collection_role(collection_id) = 'owner');
create policy "owners remove collaborators; collaborators can leave" on public.collection_collaborators for delete to authenticated
  using (user_id = (select auth.uid()) or public.collection_role(collection_id) = 'owner');
grant select, delete on public.collection_collaborators to authenticated;
grant insert (collection_id, user_id, role, invited_by) on public.collection_collaborators to authenticated;
grant update (role) on public.collection_collaborators to authenticated;

-- Saving a collection bookmarks it; it gives no edit rights. Only public collections can be saved directly.
create policy "you see your saves" on public.collection_saves for select to authenticated using (user_id = (select auth.uid()));
create policy "you save public collections" on public.collection_saves for insert to authenticated
  with check (user_id = (select auth.uid()) and exists (select 1 from public.movie_collections c where c.id = collection_id and c.visibility = 'public'));
create policy "you unsave" on public.collection_saves for delete to authenticated using (user_id = (select auth.uid()));
grant select, delete on public.collection_saves to authenticated;
grant insert (user_id, collection_id) on public.collection_saves to authenticated;

------------------------------------------------------------------------------------------------------------------
-- Functions for links, copies and honest counts.
------------------------------------------------------------------------------------------------------------------
-- Open a collection from its share link: works for public and unlisted ones (and for members of private ones).
create or replace function public.get_collection_by_share(p_share text)
returns table (id uuid, owner_id uuid, owner_username text, title text, description text, tags text[], cover_tmdb_id integer,
               visibility text, share_id text, published_at timestamptz, updated_at timestamptz, your_role text)
language sql stable security definer set search_path = '' as $$
  select c.id, c.owner_id, p.username::text, c.title, c.description, c.tags, c.cover_tmdb_id, c.visibility, c.share_id,
         c.published_at, c.updated_at, public.collection_role(c.id)
  from public.movie_collections c join public.profiles p on p.id = c.owner_id
  where c.share_id = p_share and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null)
$$;
create or replace function public.get_collection_items_by_share(p_share text)
returns table (tmdb_id integer, title text, year smallint, poster_path text, genres text[], runtime smallint, item_position integer, note text)
language sql stable security definer set search_path = '' as $$
  select f.tmdb_id, f.title, f.year, f.poster_path, f.genres, f.runtime, i.position, i.note
  from public.movie_collections c
  join public.collection_items i on i.collection_id = c.id
  join public.films f on f.tmdb_id = i.tmdb_id
  where c.share_id = p_share and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null)
  order by i.position
$$;

-- Make your own editable, private copy of a collection you can see (or open by link).
create or replace function public.copy_collection(p_share text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare src public.movie_collections; new_id uuid; me uuid := (select auth.uid());
begin
  if me is null then raise exception 'sign in to copy a collection' using errcode = '42501'; end if;
  select * into src from public.movie_collections c
   where c.share_id = p_share and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null);
  if src.id is null then raise exception 'collection not found' using errcode = 'P0002'; end if;
  insert into public.movie_collections (owner_id, title, description, tags, cover_tmdb_id, visibility, copied_from)
  values (me, left('Copy of ' || src.title, 120), src.description, src.tags, src.cover_tmdb_id, 'private', src.id)
  returning id into new_id;
  insert into public.collection_items (collection_id, tmdb_id, position, note, added_by)
  select new_id, i.tmdb_id, i.position, i.note, me from public.collection_items i where i.collection_id = src.id;
  return new_id;
end $$;

-- Save counts, only ever for public collections, counted from real saves.
create or replace function public.collection_save_count(cid uuid) returns integer
language sql stable security definer set search_path = '' as $$
  select case when exists (select 1 from public.movie_collections c where c.id = cid and c.visibility = 'public')
              then (select count(*)::integer from public.collection_saves s where s.collection_id = cid) end
$$;

revoke all on function public.get_collection_by_share(text), public.get_collection_items_by_share(text),
  public.copy_collection(text), public.collection_save_count(uuid) from public, anon, authenticated;
grant execute on function public.get_collection_by_share(text), public.get_collection_items_by_share(text), public.collection_save_count(uuid) to anon, authenticated;
grant execute on function public.copy_collection(text) to authenticated;

-- ==================== 20261018000003_sceneatlas.sql ====================
-- SceneAtlas: filming locations with their evidence. Only the server (service role) writes places, claims and
-- sources, after checking them; anyone can read checked claims. Unconfirmed candidates are never readable.

create table public.places (
  id            uuid primary key default gen_random_uuid(),
  wikidata_qid  text unique check (wikidata_qid ~ '^Q[0-9]+$'),
  osm_ref       text unique check (osm_ref ~ '^(node|way|relation)/[0-9]+$'),
  name          text not null check (char_length(name) between 1 and 200),
  country       text check (char_length(country) <= 100),
  region        text check (char_length(region) <= 120),
  lat           double precision not null check (lat between -90 and 90),
  lng           double precision not null check (lng between -180 and 180),
  precision     text not null check (precision in ('exact', 'site', 'city', 'region', 'country')),
  kind          text not null default 'unknown' check (kind in ('on_location', 'studio', 'backlot', 'unknown')),
  image         jsonb check (image is null or (image ? 'url' and image ? 'license' and image ? 'author' and image ? 'source_url')),
  accessibility text check (char_length(accessibility) <= 500),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index places_country on public.places (country);
create index places_latlng on public.places (lat, lng);
create trigger places_touch before update on public.places for each row execute function public.touch_updated_at();

create table public.location_claims (
  id                uuid primary key default gen_random_uuid(),
  tmdb_id           integer not null references public.films (tmdb_id) on delete cascade,
  wikidata_film     text check (wikidata_film ~ '^Q[0-9]+$'),
  place_id          uuid not null references public.places (id) on delete cascade,
  relation          text not null check (relation in ('filmed_at', 'studio', 'setting')),
  scene             text check (char_length(scene) <= 1000),
  behind_the_scenes text check (char_length(behind_the_scenes) <= 2000),
  status            text not null check (status in ('verified', 'sourced', 'community', 'candidate')),
  last_verified     timestamptz not null default now(),
  notes             text check (char_length(notes) <= 1000),
  unique (tmdb_id, place_id, relation)
);
create index claims_by_film on public.location_claims (tmdb_id);
create index claims_by_place on public.location_claims (place_id);
create index claims_by_status on public.location_claims (status);

create table public.claim_sources (
  id           uuid primary key default gen_random_uuid(),
  claim_id     uuid not null references public.location_claims (id) on delete cascade,
  title        text not null check (char_length(title) <= 300),
  url          text not null check (url ~ '^https://'),
  publisher    text check (char_length(publisher) <= 120),
  quote        text check (char_length(quote) <= 1200),
  method       text not null check (method in ('wikidata', 'wikipedia', 'web')),
  retrieved_at timestamptz not null default now(),
  unique (claim_id, url)
);
create index sources_by_claim on public.claim_sources (claim_id);

-- Research runs once per film; the server takes the lock by inserting the row.
create table public.research_jobs (
  tmdb_id     integer primary key references public.films (tmdb_id) on delete cascade,
  status      text not null check (status in ('running', 'done', 'failed')),
  started_at  timestamptz not null default now(),
  finished_at timestamptz,
  tokens      integer not null default 0,
  error       text check (char_length(error) <= 500)
);

-- A hard daily cap on AI spending, shared by every server instance.
create table public.ai_budget (
  day         date primary key default current_date,
  tokens_used bigint not null default 0 check (tokens_used >= 0)
);
create or replace function public.spend_ai_tokens(p_tokens integer, p_daily_limit bigint) returns boolean
language plpgsql security definer set search_path = '' as $$
declare used bigint;
begin
  insert into public.ai_budget (day, tokens_used) values (current_date, 0) on conflict (day) do nothing;
  update public.ai_budget set tokens_used = tokens_used + p_tokens
   where day = current_date and tokens_used + p_tokens <= p_daily_limit returning tokens_used into used;
  return used is not null;
end $$;
revoke all on function public.spend_ai_tokens(integer, bigint) from public, anon, authenticated;

-- Location Passport: places someone saved, wants to visit or has visited. Private.
create table public.location_passport (
  user_id    uuid not null references public.profiles (id) on delete cascade,
  place_id   uuid not null references public.places (id) on delete cascade,
  status     text not null check (status in ('saved', 'want', 'visited')),
  updated_at timestamptz not null default now(),
  primary key (user_id, place_id)
);

alter table public.places enable row level security;
revoke all on public.places from anon, authenticated;
alter table public.location_claims enable row level security;
revoke all on public.location_claims from anon, authenticated;
alter table public.claim_sources enable row level security;
revoke all on public.claim_sources from anon, authenticated;
alter table public.research_jobs enable row level security;
revoke all on public.research_jobs from anon, authenticated;
alter table public.ai_budget enable row level security;
revoke all on public.ai_budget from anon, authenticated;
alter table public.location_passport enable row level security;
revoke all on public.location_passport from anon, authenticated;

create policy "places are readable by everyone" on public.places for select to anon, authenticated using (true);
create policy "checked claims are readable by everyone" on public.location_claims for select to anon, authenticated using (status <> 'candidate');
create policy "sources of checked claims are readable" on public.claim_sources for select to anon, authenticated
  using (exists (select 1 from public.location_claims c where c.id = claim_id and c.status <> 'candidate'));
create policy "owners manage their passport" on public.location_passport for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
-- research_jobs and ai_budget have no policies: only the server can touch them.

grant select on public.places, public.location_claims, public.claim_sources to anon, authenticated;
grant select, insert, update, delete on public.location_passport to authenticated;

-- ==================== 20261019000004_screening_activity.sql ====================
-- Screening Activity: a seat for every day, lit by how much someone watched, rated and reviewed.
-- activity_days keeps one row per person per active day, updated by a trigger on diary_entries, so a month
-- is at most 31 indexed rows and nothing is recounted when a profile opens. Nobody reads it directly: the
-- functions below check who is asking against the owner's setting first.

alter table public.profiles add column activity_visibility text not null default 'private'
  check (activity_visibility in ('private', 'friends', 'public'));
grant update (activity_visibility) on public.profiles to authenticated;

create table public.activity_days (
  user_id  uuid not null references public.profiles (id) on delete cascade,
  day      date not null,
  watched  integer not null default 0 check (watched >= 0),
  rated    integer not null default 0 check (rated >= 0),
  reviewed integer not null default 0 check (reviewed >= 0),
  primary key (user_id, day)
);
alter table public.activity_days enable row level security;
revoke all on public.activity_days from anon, authenticated;
-- No policies: only the trigger and the functions below (security definer) touch it.

-- A rating or review counts on the day the film was watched, the same rule the app uses on a device.
create or replace function public.track_activity() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    update public.activity_days
       set watched = watched - 1,
           rated = rated - (old.rating is not null)::int,
           reviewed = reviewed - (coalesce(btrim(old.review), '') <> '')::int
     where user_id = old.user_id and day = old.watched_on;
    delete from public.activity_days where user_id = old.user_id and day = old.watched_on and watched <= 0;
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    insert into public.activity_days as a (user_id, day, watched, rated, reviewed)
    values (new.user_id, new.watched_on, 1, (new.rating is not null)::int, (coalesce(btrim(new.review), '') <> '')::int)
    on conflict (user_id, day) do update
      set watched = a.watched + excluded.watched, rated = a.rated + excluded.rated, reviewed = a.reviewed + excluded.reviewed;
  end if;
  return null;
end $$;
revoke all on function public.track_activity() from public, anon, authenticated;
create trigger diary_activity after insert or delete or update of watched_on, rating, review on public.diary_entries
  for each row execute function public.track_activity();

-- Anything already in diaries.
insert into public.activity_days (user_id, day, watched, rated, reviewed)
select user_id, watched_on, count(*), count(rating), count(*) filter (where coalesce(btrim(review), '') <> '')
  from public.diary_entries group by user_id, watched_on
on conflict (user_id, day) do nothing;

-- Who may see someone's activity: themselves; anyone if public; friends (they follow each other) if friends.
create or replace function public.can_view_activity(p_owner uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles p
     where p.id = p_owner
       and (p.id = (select auth.uid())
            or p.activity_visibility = 'public'
            or (p.activity_visibility = 'friends' and (select auth.uid()) is not null
                and exists (select 1 from public.follows f where f.follower_id = p_owner and f.followee_id = (select auth.uid()))
                and exists (select 1 from public.follows f where f.follower_id = (select auth.uid()) and f.followee_id = p_owner))))
$$;

-- One month of seats, the streaks and the month's top genre, in one call. p_today is the viewer's date (time
-- zones differ from the server's); it only moves the streak, and is kept within a day of the server's date.
create or replace function public.screening_month(p_owner uuid, p_month date, p_today date default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  start  date := date_trunc('month', p_month)::date;
  finish date := (date_trunc('month', p_month) + interval '1 month')::date;
  today  date := least(greatest(coalesce(p_today, current_date), current_date - 1), current_date + 1);
  result jsonb;
begin
  if not public.can_view_activity(p_owner) then return jsonb_build_object('allowed', false); end if;
  with d as (select day from public.activity_days where user_id = p_owner and day <= today),
       g as (select day, day - (row_number() over (order by day))::int as grp from d),
       runs as (select max(day) as last_day, count(*) as n from g group by grp)
  select jsonb_build_object(
    'allowed', true,
    'days', coalesce((select jsonb_object_agg(a.day::text, jsonb_build_array(a.watched, a.rated, a.reviewed))
                        from public.activity_days a where a.user_id = p_owner and a.day >= start and a.day < finish), '{}'::jsonb),
    'longest', coalesce((select max(n) from runs), 0),
    'current', coalesce((select max(n) from runs where last_day >= today - 1), 0),
    'first_day', (select min(day) from public.activity_days where user_id = p_owner),
    'titles', coalesce((select jsonb_object_agg(t.day::text, t.titles) from (
                  select e.watched_on as day, jsonb_agg(f.title order by e.created_at) as titles
                    from public.diary_entries e join public.films f on f.tmdb_id = e.tmdb_id
                   where e.user_id = p_owner and e.watched_on >= start and e.watched_on < finish group by e.watched_on) t), '{}'::jsonb),
    'top_genre', (select g2.genre from public.diary_entries e join public.films f on f.tmdb_id = e.tmdb_id
                    cross join lateral unnest(f.genres) as g2(genre)
                   where e.user_id = p_owner and e.watched_on >= start and e.watched_on < finish
                   group by g2.genre order by count(*) desc, g2.genre limit 1)
  ) into result;
  return result;
end $$;

-- One day's films, with ratings and reviews. Never private notes or tags.
create or replace function public.screening_day(p_owner uuid, p_day date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_view_activity(p_owner) then return null; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('tmdb_id', e.tmdb_id, 'title', f.title, 'year', f.year, 'poster_path', f.poster_path,
                                        'rating', e.rating, 'review', nullif(btrim(e.review), ''), 'spoiler', e.spoiler)
                     order by e.created_at)
      from public.diary_entries e join public.films f on f.tmdb_id = e.tmdb_id
     where e.user_id = p_owner and e.watched_on = p_day), '[]'::jsonb);
end $$;

revoke all on function public.can_view_activity(uuid) from public;
revoke all on function public.screening_month(uuid, date, date) from public;
revoke all on function public.screening_day(uuid, date) from public;
grant execute on function public.can_view_activity(uuid) to anon, authenticated;
grant execute on function public.screening_month(uuid, date, date) to anon, authenticated;
grant execute on function public.screening_day(uuid, date) to anon, authenticated;

-- ==================== 20261020000005_community.sql ====================
-- Community: clearly labelled demo accounts, per-review visibility, and the read paths Explore, profiles and film
-- pages use. Every function below checks the viewer and returns only safe columns (never private notes or tags).

------------------------------------------------------------------------------------------------------------------
-- Demo labelling. Set only by the server's demo importer (service role); not in any user grant, so nobody can mark
-- themselves or anyone else as demo, or remove the label.
------------------------------------------------------------------------------------------------------------------
alter table public.profiles add column is_demo boolean not null default false;
alter table public.profiles add column demo_seed_key text unique;
alter table public.movie_collections add column demo_seed_key text;
create unique index collections_demo_key on public.movie_collections (owner_id, demo_seed_key) where demo_seed_key is not null;
create index profiles_demo on public.profiles (is_demo) where is_demo;

-- What the importer did, for an audit trail. Server only.
create table public.demo_seed_runs (
  id      uuid primary key default gen_random_uuid(),
  ran_at  timestamptz not null default now(),
  ran_by  uuid references public.profiles (id) on delete set null,
  action  text not null check (action in ('seed', 'cleanup', 'dry_run')),
  report  jsonb not null default '{}'::jsonb
);
alter table public.demo_seed_runs enable row level security;
revoke all on public.demo_seed_runs from anon, authenticated;

------------------------------------------------------------------------------------------------------------------
-- Reviews: each one is private, friends-only or public. New reviews start private.
------------------------------------------------------------------------------------------------------------------
alter table public.diary_entries add column review_visibility text not null default 'private'
  check (review_visibility in ('private', 'friends', 'public'));
grant insert (review_visibility), update (review_visibility) on public.diary_entries to authenticated;
create index diary_public_reviews on public.diary_entries (tmdb_id, created_at desc) where review_visibility <> 'private' and review is not null;

-- Friends follow each other.
create or replace function public.are_friends(a uuid, b uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select a is not null and b is not null and a <> b
     and exists (select 1 from public.follows f where f.follower_id = a and f.followee_id = b)
     and exists (select 1 from public.follows f where f.follower_id = b and f.followee_id = a)
$$;
create or replace function public.can_read_review(p_owner uuid, p_visibility text) returns boolean
language sql stable security definer set search_path = '' as $$
  select p_owner = (select auth.uid()) or p_visibility = 'public'
      or (p_visibility = 'friends' and public.are_friends(p_owner, (select auth.uid())))
$$;

-- Reviews of one film that the viewer may read, newest first.
create or replace function public.film_reviews(p_tmdb integer, p_limit integer default 20, p_before timestamptz default null, p_include_demo boolean default true)
returns table (entry_id uuid, author_id uuid, username text, display_name text, avatar_url text, is_demo boolean,
               rating numeric, review text, spoiler boolean, watched_on date, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select e.id, p.id, p.username::text, p.display_name, p.avatar_url, p.is_demo, e.rating, btrim(e.review), e.spoiler, e.watched_on, e.created_at
    from public.diary_entries e join public.profiles p on p.id = e.user_id
   where e.tmdb_id = p_tmdb and coalesce(btrim(e.review), '') <> ''
     and public.can_read_review(e.user_id, e.review_visibility)
     and (p_include_demo or not p.is_demo)
     and (p_before is null or e.created_at < p_before)
   order by e.created_at desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50)
$$;

-- One person's reviews that the viewer may read, with the film.
create or replace function public.profile_reviews(p_owner uuid, p_limit integer default 20, p_before timestamptz default null)
returns table (entry_id uuid, tmdb_id integer, title text, year smallint, poster_path text,
               rating numeric, review text, spoiler boolean, review_visibility text, watched_on date, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select e.id, f.tmdb_id, f.title, f.year, f.poster_path, e.rating, btrim(e.review), e.spoiler, e.review_visibility, e.watched_on, e.created_at
    from public.diary_entries e join public.films f on f.tmdb_id = e.tmdb_id
   where e.user_id = p_owner and coalesce(btrim(e.review), '') <> ''
     and public.can_read_review(e.user_id, e.review_visibility)
     and (p_before is null or e.created_at < p_before)
   order by e.watched_on desc, e.created_at desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50)
$$;

------------------------------------------------------------------------------------------------------------------
-- Explore: public collections only. Unlisted and private ones never appear in lists, whoever is asking.
------------------------------------------------------------------------------------------------------------------
create or replace function public.explore_collections(p_q text default null, p_sort text default 'recent', p_limit integer default 24,
                                                      p_offset integer default 0, p_include_demo boolean default true, p_owner uuid default null)
returns table (id uuid, share_id text, title text, description text, tags text[], owner_id uuid, username text, display_name text,
               avatar_url text, is_demo boolean, film_count integer, covers jsonb, saves integer, saved_by_me boolean, published_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select c.id, c.share_id, c.title, c.description, c.tags, p.id, p.username::text, p.display_name, p.avatar_url, p.is_demo,
         (select count(*)::int from public.collection_items i where i.collection_id = c.id),
         coalesce((select jsonb_agg(jsonb_build_object('tmdb_id', x.tmdb_id, 'title', x.title, 'poster_path', x.poster_path) order by x.position)
                     from (select i.tmdb_id, i.position, f.title, f.poster_path from public.collection_items i
                             join public.films f on f.tmdb_id = i.tmdb_id where i.collection_id = c.id order by i.position limit 4) x), '[]'::jsonb),
         (select count(*)::int from public.collection_saves s where s.collection_id = c.id),
         exists (select 1 from public.collection_saves s where s.collection_id = c.id and s.user_id = (select auth.uid())),
         c.published_at
    from public.movie_collections c join public.profiles p on p.id = c.owner_id
   where c.visibility = 'public'
     and (p_include_demo or not p.is_demo)
     and (p_owner is null or c.owner_id = p_owner)
     and (coalesce(btrim(p_q), '') = '' or c.search @@ websearch_to_tsquery('simple', p_q))
   order by case when p_sort = 'popular' then (select count(*) from public.collection_saves s where s.collection_id = c.id) end desc nulls last,
            c.published_at desc nulls last, c.id
   limit least(greatest(coalesce(p_limit, 24), 1), 60) offset greatest(coalesce(p_offset, 0), 0)
$$;

-- People to discover, with honest counts (public collections only).
create or replace function public.community_members(p_limit integer default 24, p_offset integer default 0, p_include_demo boolean default true)
returns table (id uuid, username text, display_name text, avatar_url text, bio text, is_demo boolean,
               public_collections integer, followers integer, i_follow boolean, follows_me boolean)
language sql stable security definer set search_path = '' as $$
  select p.id, p.username::text, p.display_name, p.avatar_url, p.bio, p.is_demo,
         (select count(*)::int from public.movie_collections c where c.owner_id = p.id and c.visibility = 'public'),
         (select count(*)::int from public.follows f where f.followee_id = p.id),
         exists (select 1 from public.follows f where f.follower_id = (select auth.uid()) and f.followee_id = p.id),
         exists (select 1 from public.follows f where f.follower_id = p.id and f.followee_id = (select auth.uid()))
    from public.profiles p
   where p.onboarded and (p_include_demo or not p.is_demo) and p.id is distinct from (select auth.uid())
   order by (select count(*) from public.follows f where f.followee_id = p.id) desc, p.username
   limit least(greatest(coalesce(p_limit, 24), 1), 60) offset greatest(coalesce(p_offset, 0), 0)
$$;

-- A collection page by its share id: details, owner, films, counts and what the viewer may do. Works for public and
-- unlisted collections (anyone with the link) and for members of private ones; null for everyone else.
create or replace function public.collection_page(p_share text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', c.id, 'share_id', c.share_id, 'title', c.title, 'description', c.description, 'tags', c.tags, 'visibility', c.visibility,
    'updated_at', c.updated_at, 'role', public.collection_role(c.id),
    'owner', jsonb_build_object('id', p.id, 'username', p.username::text, 'display_name', p.display_name, 'avatar_url', p.avatar_url, 'is_demo', p.is_demo),
    'saves', case when c.visibility = 'public' then (select count(*) from public.collection_saves s where s.collection_id = c.id) end,
    'saved_by_me', exists (select 1 from public.collection_saves s where s.collection_id = c.id and s.user_id = (select auth.uid())),
    'films', coalesce((select jsonb_agg(jsonb_build_object('tmdb_id', f.tmdb_id, 'title', f.title, 'year', f.year, 'poster_path', f.poster_path,
                                                            'genres', f.genres, 'runtime', f.runtime, 'note', i.note) order by i.position)
                         from public.collection_items i join public.films f on f.tmdb_id = i.tmdb_id where i.collection_id = c.id), '[]'::jsonb))
    from public.movie_collections c join public.profiles p on p.id = c.owner_id
   where c.share_id = p_share and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null)
$$;

------------------------------------------------------------------------------------------------------------------
-- Screening Activity's day panel now honours each review's own visibility: the watch and rating show to anyone
-- allowed to see the activity, the review text only to those allowed to read that review.
------------------------------------------------------------------------------------------------------------------
create or replace function public.screening_day(p_owner uuid, p_day date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.can_view_activity(p_owner) then return null; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('tmdb_id', e.tmdb_id, 'title', f.title, 'year', f.year, 'poster_path', f.poster_path, 'rating', e.rating,
                                        'review', case when public.can_read_review(e.user_id, e.review_visibility) then nullif(btrim(e.review), '') end,
                                        'spoiler', e.spoiler)
                     order by e.created_at)
      from public.diary_entries e join public.films f on f.tmdb_id = e.tmdb_id
     where e.user_id = p_owner and e.watched_on = p_day), '[]'::jsonb);
end $$;

revoke all on function public.are_friends(uuid, uuid), public.can_read_review(uuid, text) from public;
revoke all on function public.film_reviews(integer, integer, timestamptz, boolean), public.profile_reviews(uuid, integer, timestamptz) from public;
revoke all on function public.explore_collections(text, text, integer, integer, boolean, uuid), public.community_members(integer, integer, boolean) from public;
revoke all on function public.collection_page(text) from public;
grant execute on function public.are_friends(uuid, uuid), public.can_read_review(uuid, text) to anon, authenticated;
grant execute on function public.film_reviews(integer, integer, timestamptz, boolean), public.profile_reviews(uuid, integer, timestamptz) to anon, authenticated;
grant execute on function public.explore_collections(text, text, integer, integer, boolean, uuid), public.community_members(integer, integer, boolean) to anon, authenticated;
grant execute on function public.collection_page(text) to anon, authenticated;

------------------------------------------------------------------------------------------------------------------
-- The demo importer's database side (service role only). The server resolves films with TMDB and creates the Auth
-- users with the Admin API, then hands everything to demo_seed_apply in one transaction.
-- Safety: an account is only ever touched when its Auth email is the fixture's own reserved demo address
-- (viemo.demo.*@example.com). Real users, and anything they own, are never changed.
------------------------------------------------------------------------------------------------------------------
create or replace function public.demo_seed_lookup(p_emails text[])
returns table (email text, user_id uuid, has_profile boolean, is_demo boolean, demo_seed_key text)
language sql stable security definer set search_path = '' as $$
  select u.email::text, u.id, p.id is not null, coalesce(p.is_demo, false), p.demo_seed_key
    from auth.users u left join public.profiles p on p.id = u.id
   where lower(u.email) = any (select lower(e) from unnest(p_emails) e)
$$;

create or replace function public.demo_seed_targets()
returns table (user_id uuid, email text, demo_seed_key text)
language sql stable security definer set search_path = '' as $$
  select p.id, u.email::text, p.demo_seed_key
    from public.profiles p join auth.users u on u.id = p.id
   where p.is_demo and lower(u.email) like 'viemo.demo.%@example.com'
$$;

create or replace function public.demo_seed_apply(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  a jsonb; c jsonb; w jsonb; f jsonb;
  uid uuid; em text; want text; uname text; cid uuid; keys text[];
  report jsonb := jsonb_build_object('films', 0, 'accounts', 0, 'skipped', '[]'::jsonb, 'renamed', '[]'::jsonb,
                                     'watched', 0, 'reviews', 0, 'watchlist', 0, 'collections', 0, 'collection_items', 0, 'follows', 0);
  ids jsonb := '{}'::jsonb;
  n int;
begin
  -- Films, exactly as the server resolved them from TMDB.
  for f in select * from jsonb_array_elements(coalesce(p -> 'films', '[]')) loop
    insert into public.films (tmdb_id, title, year, poster_path, genres, runtime, fetched_at)
    values ((f ->> 'tmdb_id')::int, f ->> 'title', (f ->> 'year')::smallint, nullif(f ->> 'poster_path', ''),
            coalesce((select array_agg(x) from jsonb_array_elements_text(f -> 'genres') x), '{}'), (f ->> 'runtime')::smallint, now())
    on conflict (tmdb_id) do update set title = excluded.title, year = excluded.year, poster_path = excluded.poster_path,
                                        genres = excluded.genres, runtime = coalesce(excluded.runtime, public.films.runtime), fetched_at = now();
    report := jsonb_set(report, '{films}', to_jsonb((report ->> 'films')::int + 1));
  end loop;

  for a in select * from jsonb_array_elements(coalesce(p -> 'accounts', '[]')) loop
    uid := (a ->> 'user_id')::uuid;
    select u.email into em from auth.users u where u.id = uid;
    if em is null or lower(em) <> lower(a ->> 'email') or lower(em) not like 'viemo.demo.%@example.com' then
      report := jsonb_set(report, '{skipped}', (report -> 'skipped') || jsonb_build_object('seed_key', a ->> 'seed_key', 'why', 'not the fixture''s demo Auth user'));
      continue;
    end if;
    if not exists (select 1 from public.profiles where id = uid) then
      report := jsonb_set(report, '{skipped}', (report -> 'skipped') || jsonb_build_object('seed_key', a ->> 'seed_key', 'why', 'no profile (is migration 0001 applied?)'));
      continue;
    end if;

    -- Username: the fixture's, unless someone else already has it.
    want := lower(a ->> 'username'); uname := want;
    if exists (select 1 from public.profiles where username = uname::extensions.citext and id <> uid) then
      uname := left('demo_' || want, 24);
      if exists (select 1 from public.profiles where username = uname::extensions.citext and id <> uid) then uname := null; end if;
      report := jsonb_set(report, '{renamed}', (report -> 'renamed') || jsonb_build_object('wanted', want, 'used', uname));
    end if;
    update public.profiles set
      username = coalesce(uname::extensions.citext, username), display_name = left(a ->> 'display_name', 60), bio = left(a ->> 'bio', 280),
      watchlist_visibility = case when a ->> 'watchlist_visibility' = 'public' then 'public' else 'private' end,
      activity_visibility = coalesce(nullif(a ->> 'activity_visibility', ''), 'public'),
      is_demo = true, demo_seed_key = a ->> 'seed_key', onboarded = true
    where id = uid;
    ids := ids || jsonb_build_object(a ->> 'seed_key', uid);
    report := jsonb_set(report, '{accounts}', to_jsonb((report ->> 'accounts')::int + 1));

    -- Diary, ratings and reviews: replaced, so a rerun gives the same result.
    delete from public.diary_entries where user_id = uid;
    for w in select * from jsonb_array_elements(coalesce(a -> 'watched', '[]')) loop
      insert into public.diary_entries (user_id, tmdb_id, watched_on, rating, review, spoiler, review_visibility)
      values (uid, (w ->> 'tmdb_id')::int, (w ->> 'watched_on')::date, (w ->> 'rating')::numeric, nullif(btrim(w ->> 'review'), ''), false,
              case when w ->> 'review_visibility' in ('public', 'friends') then w ->> 'review_visibility' else 'private' end);
      report := jsonb_set(report, '{watched}', to_jsonb((report ->> 'watched')::int + 1));
      if nullif(btrim(w ->> 'review'), '') is not null then report := jsonb_set(report, '{reviews}', to_jsonb((report ->> 'reviews')::int + 1)); end if;
    end loop;

    delete from public.watchlist_items where user_id = uid;
    insert into public.watchlist_items (user_id, tmdb_id) select uid, x::int from jsonb_array_elements_text(coalesce(a -> 'watchlist', '[]')) x on conflict do nothing;
    get diagnostics n = row_count;
    report := jsonb_set(report, '{watchlist}', to_jsonb((report ->> 'watchlist')::int + n));

    -- Collections, matched by seed key; ones no longer in the fixture are removed.
    keys := '{}';
    for c in select * from jsonb_array_elements(coalesce(a -> 'collections', '[]')) loop
      insert into public.movie_collections (owner_id, title, description, visibility, demo_seed_key)
      values (uid, c ->> 'title', c ->> 'description', c ->> 'visibility', c ->> 'seed_key')
      on conflict (owner_id, demo_seed_key) where demo_seed_key is not null
      do update set title = excluded.title, description = excluded.description, visibility = excluded.visibility
      returning id into cid;
      keys := keys || (c ->> 'seed_key');
      delete from public.collection_items where collection_id = cid;
      insert into public.collection_items (collection_id, tmdb_id, position, added_by)
        select cid, x.v::int, (x.o - 1)::int, uid from jsonb_array_elements_text(coalesce(c -> 'films', '[]')) with ordinality x(v, o)
        on conflict do nothing;
      get diagnostics n = row_count;
      report := jsonb_set(report, '{collection_items}', to_jsonb((report ->> 'collection_items')::int + n));
      report := jsonb_set(report, '{collections}', to_jsonb((report ->> 'collections')::int + 1));
    end loop;
    delete from public.movie_collections where owner_id = uid and demo_seed_key is not null and not (demo_seed_key = any (keys));
  end loop;

  -- Follows among demo accounts only. Follows between real people and demo accounts are left alone.
  delete from public.follows where follower_id in (select id from public.profiles where is_demo) and followee_id in (select id from public.profiles where is_demo);
  insert into public.follows (follower_id, followee_id)
    select (ids ->> (x ->> 'follower'))::uuid, (ids ->> (x ->> 'following'))::uuid from jsonb_array_elements(coalesce(p -> 'follows', '[]')) x
     where ids ? (x ->> 'follower') and ids ? (x ->> 'following') and x ->> 'follower' <> x ->> 'following'
    on conflict do nothing;
  get diagnostics n = row_count;
  report := jsonb_set(report, '{follows}', to_jsonb(n));
  return report;
end $$;

revoke all on function public.demo_seed_lookup(text[]), public.demo_seed_targets(), public.demo_seed_apply(jsonb) from public, anon, authenticated;
grant execute on function public.demo_seed_lookup(text[]), public.demo_seed_targets(), public.demo_seed_apply(jsonb) to service_role;

-- ==================== 20261021000006_wheelmo.sql ====================
-- WheelMo: a film roulette (no betting, no prizes). The database picks the winner, before any animation, from
-- the exact pool the person sees; every film in the pool has the same chance. Each spin is saved with its pool,
-- winner and status, and a request id makes a double click or a reconnect return the same spin, never a new one.

-- Supabase installs pgcrypto in the extensions schema; this makes sure of it elsewhere.
create extension if not exists pgcrypto with schema extensions;

create table public.wheel_spins (
  id             uuid primary key default gen_random_uuid(),
  request_id     uuid not null unique,
  user_id        uuid references public.profiles (id) on delete cascade,   -- null for signed-out visitors
  night_id       uuid,                                                      -- Movie Night spins (see 0007)
  mode           text not null check (mode in ('watchlist', 'playlist', 'surprise', 'group', 'decider')),
  source         text not null check (char_length(source) <= 120),         -- 'account', 'device', a share id, filters
  pool           jsonb not null check (jsonb_typeof(pool) = 'array' and jsonb_array_length(pool) between 2 and 12),
  pool_ids       integer[] not null,
  winner_index   integer not null,
  winner_tmdb_id integer not null,
  selection      text not null default 'uniform' check (selection = 'uniform'),  -- disclosed; nothing weighted
  status         text not null default 'spinning' check (status in ('spinning', 'revealed', 'confirmed', 'superseded')),
  created_at     timestamptz not null default now(),
  revealed_at    timestamptz,
  confirmed_at   timestamptz,
  check (cardinality(pool_ids) = jsonb_array_length(pool)),
  check (winner_index >= 0 and winner_index < cardinality(pool_ids) and pool_ids[winner_index + 1] = winner_tmdb_id)
);
create index spins_by_user on public.wheel_spins (user_id, created_at desc);
create index spins_by_night on public.wheel_spins (night_id, created_at desc) where night_id is not null;
-- One spin in motion per Movie Night at a time.
create unique index one_active_spin_per_night on public.wheel_spins (night_id) where status = 'spinning' and night_id is not null;

alter table public.wheel_spins enable row level security;
revoke all on public.wheel_spins from anon, authenticated;
create policy "your own spins" on public.wheel_spins for select to authenticated using (user_id = (select auth.uid()) and night_id is null);
grant select on public.wheel_spins to authenticated;
-- No insert or update grants: spins are only made and changed by the functions below.

-- A uniformly random index in [0, n) from the operating system's cryptographic generator, by rejection sampling
-- (so no index is even slightly more likely than another).
create or replace function public.wheel_pick(n integer) returns integer
language plpgsql volatile set search_path = '' as $$
declare r bigint; lim bigint;
begin
  if n < 1 then raise exception 'empty pool'; end if;
  lim := (4294967296 / n) * n;
  loop
    r := ('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint;
    exit when r < lim;
  end loop;
  return (r % n)::integer;
end $$;
revoke all on function public.wheel_pick(integer) from public, anon, authenticated;

-- The shared core: checks the pool, picks the winner, saves the spin. Not callable directly.
create or replace function public.wheel_spin_core(p_request uuid, p_user uuid, p_night uuid, p_mode text, p_source text, p_ids integer[])
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare existing public.wheel_spins; pool jsonb; ids integer[]; idx integer; made public.wheel_spins;
begin
  -- The same request again (a double click, a retry, a reconnect): the same spin, never a new winner.
  select * into existing from public.wheel_spins where request_id = p_request;
  if existing.id is not null then
    if existing.user_id is distinct from p_user then raise exception 'request id already used' using errcode = '42501'; end if;
    return to_jsonb(existing) || jsonb_build_object('repeat', true);
  end if;
  ids := array(select x from (select x, min(o) o from unnest(p_ids) with ordinality u(x, o) group by x) d order by o);
  if cardinality(ids) <> cardinality(p_ids) then raise exception 'the pool has duplicates' using errcode = '22023'; end if;
  if cardinality(ids) < 2 or cardinality(ids) > 12 then raise exception 'a wheel holds 2 to 12 films' using errcode = '22023'; end if;
  -- Every film must be a real, stored TMDB film; the snapshot takes its details from the films table, not the client.
  select jsonb_agg(jsonb_build_object('tmdb_id', f.tmdb_id, 'title', f.title, 'year', f.year, 'poster_path', f.poster_path) order by u.o)
    into pool from unnest(ids) with ordinality u(x, o) join public.films f on f.tmdb_id = u.x;
  if pool is null or jsonb_array_length(pool) <> cardinality(ids) then raise exception 'unknown film in the pool' using errcode = '22023'; end if;
  idx := public.wheel_pick(cardinality(ids));
  insert into public.wheel_spins (request_id, user_id, night_id, mode, source, pool, pool_ids, winner_index, winner_tmdb_id)
  values (p_request, p_user, p_night, p_mode, left(coalesce(p_source, ''), 120), pool, ids, idx, ids[idx + 1])
  returning * into made;
  return to_jsonb(made) || jsonb_build_object('repeat', false);
end $$;
revoke all on function public.wheel_spin_core(uuid, uuid, uuid, text, text, integer[]) from public, anon, authenticated;

-- A signed-in person's solo spin. The pool must come from where it says:
--   watchlist + 'account': every film is on their account watchlist;
--   playlist + a share id: every film is in that collection, which they can see;
--   watchlist + 'device', or surprise: real films the server has checked.
create or replace function public.spin_wheel(p_request uuid, p_mode text, p_source text, p_ids integer[]) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); cid uuid;
begin
  if me is null then raise exception 'sign in to save spins' using errcode = '42501'; end if;
  if p_mode = 'watchlist' and p_source = 'account' then
    if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.watchlist_items w where w.user_id = me and w.tmdb_id = x)) then
      raise exception 'a film in the pool is not on your watchlist' using errcode = '42501';
    end if;
  elsif p_mode = 'playlist' then
    select c.id into cid from public.movie_collections c
     where c.share_id = p_source and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null);
    if cid is null then raise exception 'collection not found' using errcode = '42501'; end if;
    if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.collection_items i where i.collection_id = cid and i.tmdb_id = x)) then
      raise exception 'a film in the pool is not in this collection' using errcode = '42501';
    end if;
  elsif not (p_mode = 'surprise' or (p_mode = 'watchlist' and p_source = 'device')) then
    raise exception 'unknown wheel source' using errcode = '22023';
  end if;
  return public.wheel_spin_core(p_request, me, null, p_mode, p_source, p_ids);
end $$;

-- Signed-out visitors spin through the server (service role), with the same checks for collections.
create or replace function public.spin_wheel_service(p_request uuid, p_mode text, p_source text, p_ids integer[]) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare cid uuid;
begin
  if p_mode = 'playlist' then
    select c.id into cid from public.movie_collections c where c.share_id = p_source and c.visibility in ('public', 'unlisted');
    if cid is null then raise exception 'collection not found' using errcode = '42501'; end if;
    if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.collection_items i where i.collection_id = cid and i.tmdb_id = x)) then
      raise exception 'a film in the pool is not in this collection' using errcode = '42501';
    end if;
  elsif not (p_mode = 'surprise' or (p_mode = 'watchlist' and p_source = 'device')) then
    raise exception 'unknown wheel source' using errcode = '22023';
  end if;
  return public.wheel_spin_core(p_request, null, null, p_mode, p_source, p_ids);
end $$;

-- The animation finished (or was skipped): the spin is revealed. Only your own.
create or replace function public.wheel_reveal(p_spin uuid) returns void
language sql volatile security definer set search_path = '' as $$
  update public.wheel_spins set status = 'revealed', revealed_at = coalesce(revealed_at, now())
   where id = p_spin and status = 'spinning' and user_id = (select auth.uid()) and night_id is null
$$;

revoke all on function public.spin_wheel(uuid, text, text, integer[]), public.spin_wheel_service(uuid, text, text, integer[]), public.wheel_reveal(uuid) from public, anon, authenticated;
grant execute on function public.spin_wheel(uuid, text, text, integer[]), public.wheel_reveal(uuid) to authenticated;
grant execute on function public.spin_wheel_service(uuid, text, text, integer[]) to service_role;

-- ==================== 20261022000007_movie_nights.sql ====================
-- Movie Night rooms: a host and friends join by code, pool films, vote privately, see results together, and can let
-- WheelMo choose (from the whole pool, or as Match Decider from the films everyone said yes to). Everything here is
-- visible only to the room's participants; each person's votes stay their own until the host shows the results.

create table public.movie_nights (
  id            uuid primary key default gen_random_uuid(),
  code          text not null unique check (code ~ '^[A-HJ-NP-Z2-9]{6}$'),
  host_id       uuid not null references public.profiles (id) on delete cascade,
  title         text not null default 'Movie Night' check (char_length(btrim(title)) between 1 and 80),
  status        text not null default 'lobby' check (status in ('lobby', 'voting', 'results', 'closed')),
  pick_tmdb_id  integer references public.films (tmdb_id),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  expires_at    timestamptz not null default now() + interval '24 hours'
);
create trigger nights_touch before update on public.movie_nights for each row execute function public.touch_updated_at();

create table public.night_participants (
  night_id  uuid not null references public.movie_nights (id) on delete cascade,
  user_id   uuid not null references public.profiles (id) on delete cascade,
  role      text not null check (role in ('host', 'guest')),
  joined_at timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  primary key (night_id, user_id)
);
create index participants_by_user on public.night_participants (user_id);

create table public.night_candidates (
  night_id   uuid not null references public.movie_nights (id) on delete cascade,
  tmdb_id    integer not null references public.films (tmdb_id),
  added_by   uuid references public.profiles (id) on delete set null,
  source     text not null check (source in ('watchlist', 'collection', 'search', 'surprise')),
  added_at   timestamptz not null default now(),
  primary key (night_id, tmdb_id)
);

create table public.night_votes (
  night_id uuid not null references public.movie_nights (id) on delete cascade,
  user_id  uuid not null references public.profiles (id) on delete cascade,
  tmdb_id  integer not null,
  vote     boolean not null,
  voted_at timestamptz not null default now(),
  primary key (night_id, user_id, tmdb_id),
  foreign key (night_id, tmdb_id) references public.night_candidates (night_id, tmdb_id) on delete cascade
);

create table public.night_picks (
  id           uuid primary key default gen_random_uuid(),
  night_id     uuid not null references public.movie_nights (id) on delete cascade,
  tmdb_id      integer not null references public.films (tmdb_id),
  spin_id      uuid references public.wheel_spins (id) on delete set null,
  how          text not null check (how in ('match', 'decider', 'wheel', 'host')),
  confirmed_by uuid references public.profiles (id) on delete set null,
  confirmed_at timestamptz not null default now()
);

alter table public.wheel_spins add constraint wheel_spins_night_fk foreign key (night_id) references public.movie_nights (id) on delete cascade;

-- Membership checks run as the definer so the policies below don't recurse.
create or replace function public.is_night_member(p_night uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.night_participants p where p.night_id = p_night and p.user_id = (select auth.uid()))
$$;
create or replace function public.is_night_host(p_night uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.movie_nights n where n.id = p_night and n.host_id = (select auth.uid()))
$$;
revoke all on function public.is_night_member(uuid), public.is_night_host(uuid) from public, anon;
grant execute on function public.is_night_member(uuid), public.is_night_host(uuid) to authenticated;

alter table public.movie_nights enable row level security;      revoke all on public.movie_nights from anon, authenticated;
alter table public.night_participants enable row level security; revoke all on public.night_participants from anon, authenticated;
alter table public.night_candidates enable row level security;  revoke all on public.night_candidates from anon, authenticated;
alter table public.night_votes enable row level security;       revoke all on public.night_votes from anon, authenticated;
alter table public.night_picks enable row level security;       revoke all on public.night_picks from anon, authenticated;
-- Reads only; every change goes through the functions below, which check who is asking and the room's stage.
create policy "members see their nights" on public.movie_nights for select to authenticated using (public.is_night_member(id));
create policy "members see who's in" on public.night_participants for select to authenticated using (public.is_night_member(night_id));
create policy "members see the pool" on public.night_candidates for select to authenticated using (public.is_night_member(night_id));
create policy "you see only your own votes" on public.night_votes for select to authenticated using (user_id = (select auth.uid()));
create policy "members see the picks" on public.night_picks for select to authenticated using (public.is_night_member(night_id));
create policy "members see the room's spins" on public.wheel_spins for select to authenticated using (night_id is not null and public.is_night_member(night_id));
grant select on public.movie_nights, public.night_participants, public.night_candidates, public.night_votes, public.night_picks to authenticated;

-- Live updates: every change to a room also touches its movie_nights row, and only that table is published to
-- Supabase Realtime (which applies the policy above, so only members hear about it). The event carries no votes or
-- films; each screen then asks night_state for what it may see. Skipped where Realtime isn't installed.
do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'movie_nights') then
    alter publication supabase_realtime add table public.movie_nights;
  end if;
end $$;

------------------------------------------------------------------------------------------------------------------
-- Room actions
------------------------------------------------------------------------------------------------------------------
create or replace function public.create_night(p_title text default null) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); c text; nid uuid; alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
begin
  if me is null then raise exception 'sign in to host a Movie Night' using errcode = '42501'; end if;
  if (select count(*) from public.movie_nights where host_id = me and created_at > now() - interval '1 hour') >= 10 then
    raise exception 'too many rooms' using errcode = '54000';
  end if;
  loop
    c := (select string_agg(substr(alphabet, 1 + (get_byte(extensions.gen_random_bytes(1), 0) % 32), 1), '') from generate_series(1, 6));
    exit when not exists (select 1 from public.movie_nights where code = c);
  end loop;
  insert into public.movie_nights (code, host_id, title) values (c, me, coalesce(nullif(left(btrim(p_title), 80), ''), 'Movie Night')) returning id into nid;
  insert into public.night_participants (night_id, user_id, role) values (nid, me, 'host');
  return jsonb_build_object('id', nid, 'code', c);
end $$;

create or replace function public.join_night(p_code text) returns uuid
language plpgsql volatile security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); n public.movie_nights;
begin
  if me is null then raise exception 'sign in to join' using errcode = '42501'; end if;
  select * into n from public.movie_nights where code = upper(btrim(p_code));
  if n.id is null or n.expires_at < now() or n.status = 'closed' then raise exception 'no open room with that code' using errcode = 'P0002'; end if;
  insert into public.night_participants (night_id, user_id, role) values (n.id, me, 'guest') on conflict (night_id, user_id) do update set last_seen = now();
  update public.movie_nights set updated_at = now() where id = n.id;
  return n.id;
end $$;

create or replace function public.night_heartbeat(p_night uuid) returns void
language sql volatile security definer set search_path = '' as $$
  update public.night_participants set last_seen = now() where night_id = p_night and user_id = (select auth.uid())
$$;

-- Add films to the pool while the room is in the lobby. Where they come from is checked:
--   watchlist: your own account watchlist; collection: a collection you can open (by share id);
--   search / surprise: real films the server has already checked with TMDB.
create or replace function public.night_add(p_night uuid, p_ids integer[], p_source text, p_ref text default null) returns integer
language plpgsql volatile security definer set search_path = '' as $$
declare me uuid := (select auth.uid()); n public.movie_nights; cid uuid; added integer;
begin
  select * into n from public.movie_nights where id = p_night;
  if n.id is null or not public.is_night_member(p_night) then raise exception 'not in this room' using errcode = '42501'; end if;
  if n.status <> 'lobby' then raise exception 'the pool is locked once voting starts' using errcode = '55000'; end if;
  if p_source = 'watchlist' then
    if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.watchlist_items w where w.user_id = me and w.tmdb_id = x)) then
      raise exception 'not on your watchlist' using errcode = '42501'; end if;
  elsif p_source = 'collection' then
    select c.id into cid from public.movie_collections c where c.share_id = p_ref and (c.visibility in ('public', 'unlisted') or public.collection_role(c.id) is not null);
    if cid is null or exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.collection_items i where i.collection_id = cid and i.tmdb_id = x)) then
      raise exception 'not in a collection you can open' using errcode = '42501'; end if;
  elsif p_source not in ('search', 'surprise') then
    raise exception 'unknown source' using errcode = '22023';
  end if;
  if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.films f where f.tmdb_id = x)) then
    raise exception 'unknown film' using errcode = '22023'; end if;
  if (select count(*) from public.night_candidates where night_id = p_night) + cardinality(p_ids) > 40 then
    raise exception 'a room holds up to 40 films' using errcode = '54000'; end if;
  insert into public.night_candidates (night_id, tmdb_id, added_by, source) select p_night, x, me, p_source from unnest(p_ids) x on conflict do nothing;
  get diagnostics added = row_count;
  update public.movie_nights set updated_at = now() where id = p_night;
  return added;
end $$;

create or replace function public.night_remove(p_night uuid, p_tmdb integer) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not exists (select 1 from public.movie_nights where id = p_night and status = 'lobby') or not public.is_night_member(p_night) then raise exception 'the pool is locked' using errcode = '55000'; end if;
  delete from public.night_candidates where night_id = p_night and tmdb_id = p_tmdb
    and (added_by = (select auth.uid()) or public.is_night_host(p_night));
  update public.movie_nights set updated_at = now() where id = p_night;
end $$;

-- Host moves the room between stages.
create or replace function public.night_stage(p_night uuid, p_status text) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare n public.movie_nights;
begin
  select * into n from public.movie_nights where id = p_night;
  if n.id is null or n.host_id <> (select auth.uid()) then raise exception 'only the host can do that' using errcode = '42501'; end if;
  if not ((n.status = 'lobby' and p_status = 'voting') or (n.status = 'voting' and p_status in ('results', 'lobby')) or (n.status = 'results' and p_status in ('closed', 'voting')) or (n.status = 'lobby' and p_status = 'closed')) then
    raise exception 'can''t go from % to %', n.status, p_status using errcode = '55000';
  end if;
  if p_status = 'voting' and (select count(*) from public.night_candidates where night_id = p_night) < 2 then
    raise exception 'add at least two films first' using errcode = '55000';
  end if;
  update public.movie_nights set status = p_status where id = p_night;
end $$;

-- A private yes or no while voting is open.
create or replace function public.night_vote(p_night uuid, p_tmdb integer, p_vote boolean) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not public.is_night_member(p_night) then raise exception 'not in this room' using errcode = '42501'; end if;
  if not exists (select 1 from public.movie_nights where id = p_night and status = 'voting') then raise exception 'voting isn''t open' using errcode = '55000'; end if;
  insert into public.night_votes (night_id, user_id, tmdb_id, vote) values (p_night, (select auth.uid()), p_tmdb, p_vote)
  on conflict (night_id, user_id, tmdb_id) do update set vote = excluded.vote, voted_at = now();
  update public.movie_nights set updated_at = now() where id = p_night;
end $$;

-- Everything a participant may see, in one call. Votes: during voting only how many each person has cast; after
-- the host shows results, totals per film and the shortlist everyone said yes to. Never who voted what.
create or replace function public.night_state(p_night uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare n public.movie_nights; me uuid := (select auth.uid()); shown boolean; voters integer;
begin
  select * into n from public.movie_nights where id = p_night;
  if n.id is null or not public.is_night_member(p_night) then return null; end if;
  shown := n.status in ('results', 'closed');
  select count(distinct user_id) into voters from public.night_votes where night_id = p_night;
  return jsonb_build_object(
    'id', n.id, 'code', n.code, 'title', n.title, 'status', n.status, 'host_id', n.host_id, 'is_host', n.host_id = me, 'me', me,
    'pick_tmdb_id', n.pick_tmdb_id, 'expires_at', n.expires_at,
    'participants', coalesce((select jsonb_agg(jsonb_build_object('user_id', p.user_id, 'role', p.role, 'username', pr.username::text, 'display_name', pr.display_name,
        'avatar_url', pr.avatar_url, 'is_demo', pr.is_demo, 'last_seen', p.last_seen,
        'votes_cast', (select count(*) from public.night_votes v where v.night_id = p_night and v.user_id = p.user_id)) order by p.joined_at)
      from public.night_participants p join public.profiles pr on pr.id = p.user_id where p.night_id = p_night), '[]'::jsonb),
    'candidates', coalesce((select jsonb_agg(jsonb_build_object('tmdb_id', f.tmdb_id, 'title', f.title, 'year', f.year, 'poster_path', f.poster_path,
        'genres', f.genres, 'runtime', f.runtime, 'source', c.source, 'added_by', c.added_by, 'mine', c.added_by = me,
        'my_vote', (select v.vote from public.night_votes v where v.night_id = p_night and v.user_id = me and v.tmdb_id = c.tmdb_id),
        'yes', case when shown then (select count(*) from public.night_votes v where v.night_id = p_night and v.tmdb_id = c.tmdb_id and v.vote) end,
        'no', case when shown then (select count(*) from public.night_votes v where v.night_id = p_night and v.tmdb_id = c.tmdb_id and not v.vote) end) order by c.added_at)
      from public.night_candidates c join public.films f on f.tmdb_id = c.tmdb_id where c.night_id = p_night), '[]'::jsonb),
    'voters', voters,
    'shortlist', case when shown then coalesce((select jsonb_agg(c.tmdb_id order by c.added_at) from public.night_candidates c
        where c.night_id = p_night and voters > 0
          and (select count(*) from public.night_votes v where v.night_id = p_night and v.tmdb_id = c.tmdb_id and v.vote) = voters), '[]'::jsonb) end,
    'spin', (select to_jsonb(s) from public.wheel_spins s where s.night_id = p_night order by s.created_at desc limit 1),
    'picks', coalesce((select jsonb_agg(jsonb_build_object('tmdb_id', k.tmdb_id, 'title', f.title, 'how', k.how, 'at', k.confirmed_at) order by k.confirmed_at desc)
      from public.night_picks k join public.films f on f.tmdb_id = k.tmdb_id where k.night_id = p_night), '[]'::jsonb)
  );
end $$;

-- The host spins for the room. group: any 2–12 films from the room's pool. decider: exactly the films every voter said
-- yes to (after results), so a random pick is only ever made between films the whole group accepted.
create or replace function public.spin_night(p_request uuid, p_night uuid, p_mode text, p_ids integer[]) returns jsonb
language plpgsql volatile security definer set search_path = '' as $$
declare n public.movie_nights; short integer[]; voters integer; existing public.wheel_spins; made jsonb;
begin
  select * into n from public.movie_nights where id = p_night;
  if n.id is null or n.host_id <> (select auth.uid()) then raise exception 'only the host can spin for the room' using errcode = '42501'; end if;
  -- The same request again (a double click, a retry, a reconnect) returns the same spin, never a new winner.
  select * into existing from public.wheel_spins where request_id = p_request;
  if existing.id is not null then
    if existing.night_id is distinct from p_night then raise exception 'request id already used' using errcode = '42501'; end if;
    return to_jsonb(existing) || jsonb_build_object('repeat', true);
  end if;
  if n.status = 'closed' then raise exception 'this Movie Night is over' using errcode = '55000'; end if;
  if exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.night_candidates c where c.night_id = p_night and c.tmdb_id = x)) then
    raise exception 'every film must be in the room''s pool' using errcode = '42501';
  end if;
  if p_mode = 'decider' then
    if n.status <> 'results' then raise exception 'Match Decider needs the results' using errcode = '55000'; end if;
    select count(distinct user_id) into voters from public.night_votes where night_id = p_night;
    short := array(select c.tmdb_id from public.night_candidates c where c.night_id = p_night and voters > 0
                    and (select count(*) from public.night_votes v where v.night_id = p_night and v.tmdb_id = c.tmdb_id and v.vote) = voters);
    if (select array_agg(x order by x) from unnest(p_ids) x) is distinct from (select array_agg(x order by x) from unnest(short) x) then
      raise exception 'Match Decider spins exactly the films everyone said yes to' using errcode = '42501';
    end if;
  elsif p_mode <> 'group' then
    raise exception 'unknown mode' using errcode = '22023';
  end if;
  -- A spin older than its animation counts as revealed; one still turning blocks a second (unique index).
  update public.wheel_spins set status = 'revealed', revealed_at = now() where night_id = p_night and status = 'spinning' and created_at < now() - interval '7 seconds';
  made := public.wheel_spin_core(p_request, (select auth.uid()), p_night, p_mode, n.code, p_ids);
  update public.movie_nights set updated_at = now() where id = p_night;
  return made;
end $$;

-- The host confirms tonight's film; it goes into the room's history for everyone.
create or replace function public.night_confirm(p_night uuid, p_tmdb integer, p_how text, p_spin uuid default null) returns void
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not public.is_night_host(p_night) then raise exception 'only the host confirms' using errcode = '42501'; end if;
  if not exists (select 1 from public.night_candidates where night_id = p_night and tmdb_id = p_tmdb) then raise exception 'not in the pool' using errcode = '42501'; end if;
  if p_spin is not null and not exists (select 1 from public.wheel_spins where id = p_spin and night_id = p_night and winner_tmdb_id = p_tmdb) then
    raise exception 'that spin chose a different film' using errcode = '42501'; end if;
  insert into public.night_picks (night_id, tmdb_id, spin_id, how, confirmed_by) values (p_night, p_tmdb, p_spin, p_how, (select auth.uid()));
  update public.movie_nights set pick_tmdb_id = p_tmdb, status = 'closed' where id = p_night;
  update public.wheel_spins set status = 'confirmed', confirmed_at = now() where id = p_spin;
end $$;

-- Your recent rooms.
create or replace function public.my_nights() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'code', n.code, 'title', n.title, 'status', n.status, 'is_host', n.host_id = (select auth.uid()),
    'pick', (select f.title from public.films f where f.tmdb_id = n.pick_tmdb_id), 'created_at', n.created_at) order by n.created_at desc), '[]'::jsonb)
  from public.movie_nights n join public.night_participants p on p.night_id = n.id and p.user_id = (select auth.uid())
  where n.created_at > now() - interval '30 days'
$$;

revoke all on function public.create_night(text), public.join_night(text), public.night_heartbeat(uuid), public.night_add(uuid, integer[], text, text),
  public.night_remove(uuid, integer), public.night_stage(uuid, text), public.night_vote(uuid, integer, boolean), public.night_state(uuid),
  public.spin_night(uuid, uuid, text, integer[]), public.night_confirm(uuid, integer, text, uuid), public.my_nights() from public, anon;
grant execute on function public.create_night(text), public.join_night(text), public.night_heartbeat(uuid), public.night_add(uuid, integer[], text, text),
  public.night_remove(uuid, integer), public.night_stage(uuid, text), public.night_vote(uuid, integer, boolean), public.night_state(uuid),
  public.spin_night(uuid, uuid, text, integer[]), public.night_confirm(uuid, integer, text, uuid), public.my_nights() to authenticated;

-- ==================== 20261023000008_private_usernames.sql ====================
-- New accounts now go straight into the app after signing up with a password, often without visiting profile setup.
-- So a new account's starting username no longer comes from its email address: it comes from the name the person
-- gave when signing up (if any), or "member", plus a random ending. Nothing from an email address is ever public.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  base text := left(regexp_replace(lower(coalesce(new.raw_user_meta_data ->> 'display_name', '')), '[^a-z0-9_]', '', 'g'), 16);
  candidate text;
begin
  if char_length(base) < 3 then base := 'member'; end if;
  loop
    candidate := base || '_' || substr(md5(random()::text || clock_timestamp()::text), 1, 4);
    exit when not exists (select 1 from public.profiles p where p.username = candidate::extensions.citext);
  end loop;
  insert into public.profiles (id, username, display_name)
  values (new.id, candidate, nullif(left(coalesce(new.raw_user_meta_data ->> 'display_name', ''), 60), ''));
  return new;
end $$;
revoke all on function public.handle_new_user() from public, anon, authenticated;

notify pgrst, 'reload schema';
commit;
